    "textEn": "SELECT TOP i.name, i.types, i.orders\nFROM items i\nWHERE EXISTS(SELECT VALUE t FROM t IN i.types WHERE t.name = 'fruit')\nORDER BY i.types DESC",
    "textZh": "SELECT TOP i.name, i.types, i.orders\nFROM items i\nWHERE EXISTS(SELECT VALUE t FROM t IN i.types WHERE t.name = 'fruit')\nORDER BY i.types DESC"
