    "text": "SELECT TOP i.name, i.types, i.orders\nFROM items i\nWHERE ARRAY_CONTAINS(i.types, {name: 'fruit'})\nORDER BY i.orders DESC",
    "textEn": "SELECT TOP i.name, i.types, i.orders\nFROM items i\nWHERE ARRAY_CONTAINS(i.types, {name: 'fruit'})\nORDER BY i.orders DESC",
    "textZh": "SELECT TOP i.name, i.types, i.orders\nFROM items i\nWHERE ARRAY_CONTAINS(i.types, {name: 'fruit'})\nORDER BY i.orders DESC"
