  "template": "{\n  \"indexingMode\": {{1}}\n  \"automatic\": false,\n  \"includedPaths\": {{2}}\n  \"excludedPaths\":[{\"path\": \"/*\"}]\n}",
  "templateEn": "{\n  \"indexingMode\": {{1}}\n  \"automatic\": false,\n  \"includedPaths\": {{2}}\n  \"excludedPaths\":[{\"path\": \"/*\"}]\n}",
